--
-- Definition of trigger `trg_relatorio_mensal_ai`
--

DROP TRIGGER /*!50030 IF EXISTS */ `trg_relatorio_mensal_ai`;

DELIMITER $$

CREATE DEFINER = `root`@`localhost` TRIGGER `trg_relatorio_mensal_ai` AFTER INSERT ON `tb_item_venda` FOR EACH ROW BEGIN
    DECLARE v_data DATE;
    DECLARE v_categoria VARCHAR(50);

    -- Data da venda (documentos 1 ou 2)
    SELECT DATE(v.dataVenda)
    INTO v_data
    FROM tb_venda v
    WHERE v.codigo = NEW.codigo_venda
      AND v.status_eliminado = 'false'
      AND v.fk_documento IN (1, 2)
    LIMIT 1;

    -- Só continua se encontrou venda válida
    IF v_data IS NOT NULL THEN

        -- Categoria do produto
        SELECT tp.designacao
        INTO v_categoria
        FROM tb_produto p
        JOIN tb_tipo_produto tp 
            ON tp.codigo = p.cod_Tipo_Produto
        WHERE p.codigo = NEW.codigo_produto
        LIMIT 1;

        -- Garante registo do relatório
        IF NOT EXISTS (
            SELECT 1 
            FROM relatorio_mensal 
            WHERE data_relatorio = v_data
        ) THEN
            VALUES (v_data);
        END IF;

        -- Atualiza totais por categoria
        CASE v_categoria
            WHEN 'CARNE BOVINA' THEN
                UPDATE relatorio_mensal 
                SET carne_bovina = IFNULL(carne_bovina,0) + NEW.total
                WHERE data_relatorio = v_data;

            WHEN 'CARNE SUINA' THEN
                UPDATE relatorio_mensal 
                SET carne_suina = IFNULL(carne_suina,0) + NEW.total
                WHERE data_relatorio = v_data;

            WHEN 'CARNE CAPRINA' THEN
                UPDATE relatorio_mensal 
                SET carne_caprina = IFNULL(carne_caprina,0) + NEW.total
                WHERE data_relatorio = v_data;

            WHEN 'CARNE OVINA' THEN
                UPDATE relatorio_mensal 
                SET carne_ovina = IFNULL(carne_ovina,0) + NEW.total
                WHERE data_relatorio = v_data;

            WHEN 'AVES' THEN
                UPDATE relatorio_mensal 
                SET aves = IFNULL(aves,0) + NEW.total
                WHERE data_relatorio = v_data;

            WHEN 'OVOS' THEN
                UPDATE relatorio_mensal 
                SET ovos = IFNULL(ovos,0) + NEW.total
                WHERE data_relatorio = v_data;

            WHEN 'ENCHIDOS' THEN
                UPDATE relatorio_mensal 
                SET enchidos = IFNULL(enchidos,0) + NEW.total
                WHERE data_relatorio = v_data;

            WHEN 'SAL' THEN
                UPDATE relatorio_mensal 
                SET sal = IFNULL(sal,0) + NEW.total
                WHERE data_relatorio = v_data;

            WHEN 'TEMPEROS' THEN
                UPDATE relatorio_mensal 
                SET temperos = IFNULL(temperos,0) + NEW.total
                WHERE data_relatorio = v_data;

            WHEN 'PEIXES' THEN
                UPDATE relatorio_mensal 
                SET peixes = IFNULL(peixes,0) + NEW.total
                WHERE data_relatorio = v_data;
        END CASE;

    END IF;

END $$

DELIMITER ;

