--
-- Definition of function `cai`
--

DROP FUNCTION IF EXISTS `cai`;

DELIMITER $$

/*!50003 SET @TEMP_SQL_MODE=@@SQL_MODE, SQL_MODE='STRICT_TRANS_TABLES,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ $$
CREATE DEFINER=`root`@`localhost` FUNCTION `cai`(
	$cod_usuario int
) RETURNS datetime
begin
	declare $data_fecho datetime default null;
	select data_fecho  from caixa where pk_caixa  =
	( select max(pk_caixa) from caixa where cod_usuario_abertura  = $cod_usuario) into $data_fecho;
	return $data_fecho;
END $$
/*!50003 SET SESSION SQL_MODE=@TEMP_SQL_MODE */  $$

DELIMITER ;

