--
-- Definition of function `exiteAssociado`
--

DROP FUNCTION IF EXISTS `exiteAssociado`;

DELIMITER $$

/*!50003 SET @TEMP_SQL_MODE=@@SQL_MODE, SQL_MODE='STRICT_TRANS_TABLES,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ $$
CREATE DEFINER=`root`@`localhost` FUNCTION `exiteAssociado`(
	$cod_pai int
) RETURNS tinyint(1)
begin
	declare $tamanho int default 0; 
	select count(*) from tb_produto where cod_pai = $cod_pai into $tamanho;
	if $tamanho > 0 then return true;
	else return false;
	end if;
end $$
/*!50003 SET SESSION SQL_MODE=@TEMP_SQL_MODE */  $$

DELIMITER ;

