DROP FUNCTION IF EXISTS `fn_calcula_preco_medio`;

DELIMITER $$

/*!50003 SET @TEMP_SQL_MODE=@@SQL_MODE, SQL_MODE='STRICT_TRANS_TABLES,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ $$
CREATE DEFINER=`root`@`localhost` FUNCTION `fn_calcula_preco_medio`(
    p_produto INT,
    p_preco_novo DECIMAL(10,2),
    p_qtd_entrar INT
) RETURNS decimal(10,2)
    DETERMINISTIC
BEGIN
    DECLARE qtd_existente INT DEFAULT 0;
    DECLARE preco_medio_atual DECIMAL(10,2) DEFAULT 0;
    DECLARE peso_novo INT DEFAULT 0;
    DECLARE novo_preco_medio DECIMAL(10,2) DEFAULT 0;

    -- Pega a quantidade existente no estoque
    SELECT SUM(quantidade_existente)
    INTO qtd_existente
    FROM tb_stock
    WHERE cod_produto_codigo = p_produto;

    -- Pega o preco_medio atual do último registro do produto
    SELECT preco_medio
    INTO preco_medio_atual
    FROM tb_preco
    WHERE fk_produto = p_produto
    ORDER BY pk_preco DESC
    LIMIT 1;

    -- Define o peso da nova entrada
    SET peso_novo = IF(p_qtd_entrar > 0, p_qtd_entrar, qtd_existente);

    -- Calcula o preço médio ponderado
    SET novo_preco_medio = 
        (preco_medio_atual * qtd_existente + p_preco_novo * peso_novo) 
        / GREATEST(qtd_existente + peso_novo, 1); -- evita divisão por 0

    RETURN novo_preco_medio;
END $$
/*!50003 SET SESSION SQL_MODE=@TEMP_SQL_MODE */  $$

DELIMITER ;

--
-- Definition of function `getDataAberturaCaixaByUsuario`
--

DROP FUNCTION IF EXISTS `getDataAberturaCaixaByUsuario`;

DELIMITER $$

/*!50003 SET @TEMP_SQL_MODE=@@SQL_MODE, SQL_MODE='STRICT_TRANS_TABLES,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ $$
CREATE DEFINER=`root`@`localhost` FUNCTION `getDataAberturaCaixaByUsuario`(
	$cod_usuario int,
	$data_caixa date
) RETURNS datetime
begin
	declare $data_abertura datetime;
	select data_abertura  from caixa where pk_caixa  = 
	( select min(pk_caixa) from caixa where cod_usuario_abertura = $cod_usuario and date(data_abertura) = $data_caixa ) into $data_abertura ;

	return $data_abertura;
end $$
/*!50003 SET SESSION SQL_MODE=@TEMP_SQL_MODE */  $$

DELIMITER ;

