--

DROP FUNCTION IF EXISTS `getNumeroPecasLavandaria`;

DELIMITER $$

/*!50003 SET @TEMP_SQL_MODE=@@SQL_MODE, SQL_MODE='STRICT_TRANS_TABLES,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ $$
CREATE DEFINER=`root`@`localhost` FUNCTION `getNumeroPecasLavandaria`(
	$status boolean,
	$codFact varchar(100)
) RETURNS int(11)
begin
	
	declare $qtd int default 0;
	select 
		COUNT(*) 
	from tb_item_venda i
	inner join tb_venda v1 on v1.codigo = i.codigo_venda 
	where i.status_entrega = $status
	and v1.cod_fact = $codFact into $qtd;
	return $qtd;

END $$
