--
-- Definition of function `getPosicaoItensTicketAssociados`
--

DROP FUNCTION IF EXISTS `getPosicaoItensTicketAssociados`;

DELIMITER $$

/*!50003 SET @TEMP_SQL_MODE=@@SQL_MODE, SQL_MODE='STRICT_TRANS_TABLES,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ $$
CREATE DEFINER=`root`@`localhost` FUNCTION `getPosicaoItensTicketAssociados`(
	$cod_pai int , 
	$designacao_pai varchar(300),
	$codFact varchar(100), 
	$posicao int , 
	$nome_cliente varchar(200),
	$telefone_cliente varchar(100),
	$usuario varchar(100),
	$data_entrega date , 
	$obs varchar(500),
	$cod_venda int ) RETURNS int(11)
begin
	declare $designacao varchar(200);
	declare $tamanho, cont int;
	declare itens cursor for ( select designacao from tb_produto where cod_pai = $cod_pai );	
	select count(*) from tb_produto where cod_pai = $cod_pai into $tamanho;
	set cont = 1;
	open itens;
	while cont <= $tamanho do 
		fetch itens into $designacao;
			$designacao ,
			$designacao_pai,
			$codFact, 
			$posicao, 
			$nome_cliente,
			$telefone_cliente, 
			$usuario,
			$data_entrega, 
			$obs,
			$cod_venda
			);
		set $posicao = $posicao + 1;
		set cont = cont + 1;
	end while;
	close itens;

	return $posicao;
end $$
/*!50003 SET SESSION SQL_MODE=@TEMP_SQL_MODE */  $$

DELIMITER ;

