CREATE DEFINER=`root`@`localhost` FUNCTION `getSaldoActual`(















	$cliente_id int,















    $data_inicio date















	































) RETURNS decimal(30,2)
BEGIN































	DECLARE SALDO_ACTUAL DECIMAL(30,2) DEFAULT 0.0;















    















    SELECT 















	saldo_actual 















FROM 















	extrato_conta_cliente 















WHERE 















	pk_extrato_conta_cliente = ( SELECT  MAX( pk_extrato_conta_cliente  ) FROM extrato_conta_cliente  WHERE DATE( data_hora ) = ( SELECT DATE_SUB($data_inicio, INTERVAL 1 DAY ) )   AND cliente_id = $cliente_id) 















    















INTO SALDO_ACTUAL;































SELECT IFNULL(SALDO_ACTUAL, 0.0) INTO SALDO_ACTUAL;















































RETURN SALDO_ACTUAL;















END $$
/*!50003 SET SESSION SQL_MODE=@TEMP_SQL_MODE */  $$

