--
-- Definition of function `getValorPendenteBySeguradora`
--

DROP FUNCTION IF EXISTS `getValorPendenteBySeguradora`;

DELIMITER $$

/*!50003 SET @TEMP_SQL_MODE=@@SQL_MODE, SQL_MODE='STRICT_TRANS_TABLES,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ $$
CREATE DEFINER=`root`@`localhost` FUNCTION `getValorPendenteBySeguradora`(
		$cod_seguradora int
) RETURNS decimal(10,2)
begin
	
	declare total,   total_pendente decimal(10, 2) default 0;
	declare $tamanho, $contagem, $cod_venda int default 0;
	
	declare cursor_faturas cursor for (select 
					   v.codigo ,
					   v.cod_fact 
					from  tb_venda v
					inner join tb_cliente c on c.codigo  = v.codigo_cliente 
					inner join entidade e on e.pk_entidade  = c.fk_entidade 
					inner join entidade_seguradora s on s.pk_entidade_seguradora = c.fk_entidade_seguradora
					where c.fk_entidade_seguradora  = 5
					and v.status_eliminado  = 'false'
					and v.fk_documento = 2
	);

	select count(*)  from  tb_venda v
					inner join tb_cliente c on c.codigo  = v.codigo_cliente 
					inner join entidade e on e.pk_entidade  = c.fk_entidade 
					inner join entidade_seguradora s on s.pk_entidade_seguradora = c.fk_entidade_seguradora
					where c.fk_entidade_seguradora  = $cod_seguradora
					and v.status_eliminado  = 'false'
					and v.fk_documento = 2 into $tamanho; 

	open cursor_faturas ;
	

	set $contagem = 1; 
	while $contagem <= $tamanho do
		 fetch cursor_faturas into $cod_venda;
		 	
    	 select valor_pendente from amortizacao_divida where pk_amortizacao_divida  = 
				(select  max(pk_amortizacao_divida) from amortizacao_divida where fk_venda = $cod_venda   ) into total;
		set total_pendente = total_pendente + total;
		  set $contagem = $contagem + 1;
	end while;
	close cursor_faturas;
		
	RETURN total_pendente;
end $$
/*!50003 SET SESSION SQL_MODE=@TEMP_SQL_MODE */  $$

DELIMITER ;

