--
-- Definition of procedure `actualiza_iva`
--

DROP PROCEDURE IF EXISTS `actualiza_iva`;

DELIMITER $$

/*!50003 SET @TEMP_SQL_MODE=@@SQL_MODE, SQL_MODE='NO_ENGINE_SUBSTITUTION' */ $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `actualiza_iva`(

	$id_imposto int,

    $id_tipo_produto int

)
BEGIN







	declare $fk_produto int default 0;

	declare cont int default 0;

    declare size int default 0;

    

    

	declare produtos cursor for select codigo from tb_produto ;

    

    

    select count(*) from tb_produto into size;

    

    open produtos;

    

    while cont < size do

    

		fetch produtos into $fk_produto;

        


		set cont = cont + 1;

        

        

        

    end while;

    close produtos;

    

    select * from produto_imposto;

    





END $$
