--
-- Definition of procedure `buscar_factura_pendentes_por_cliente`
--

DROP PROCEDURE IF EXISTS `buscar_factura_pendentes_por_cliente`;

DELIMITER $$

/*!50003 SET @TEMP_SQL_MODE=@@SQL_MODE, SQL_MODE='STRICT_TRANS_TABLES,STRICT_ALL_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,TRADITIONAL,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `buscar_factura_pendentes_por_cliente`(















	cod_cliente int















)
BEGIN















	declare done int default 0;















    declare cont int default 0;















    declare tamanho int;















    declare total_amortizacoes, total_pendente decimal(10,2) default 0.00;















    















    















    declare $codigo int default 0;















    declare $data_venda datetime;















    declare $total_venda, $desconto_total, $total_iva decimal(10,2);















    declare $cod_fact varchar(45);















    















    declare facturas cursor for 















								select 















									codigo,















									dataVenda,















                                    total_venda,















                                    desconto_total,















                                    total_iva,















                                    cod_fact















								from 















									tb_venda v, 















                                    documento d















								where 















										v.fk_documento = d.pk_documento















										and d.pk_documento = 2















										and v.codigo_cliente = cod_cliente;















	















         select count(*) from tb_venda v, documento d where v.fk_documento = d.pk_documento and d.pk_documento = 2 and v.codigo_cliente = cod_cliente into tamanho;                         















                     















		  















		 call tabela_facturas_temporaria(); 















		 open facturas;















		 while cont < tamanho do















				set cont = cont + 1;















                fetch facturas into $codigo ,$data_venda,  $total_venda,  $desconto_total, $total_iva, $cod_fact;















                select getTotalAmortizacoesByCodFact( $codigo ) into total_amortizacoes;















				select getValorPendente( $codigo ) into total_pendente;















                















                if $total_venda > total_amortizacoes then















                






























								data_venda,  















								total_venda,  















								desconto_total,















								total_iva, 















                                total_amortizacao,















                                valor_pendente,















								cod_fact















						)















						values(















								$data_venda,  















								$total_venda,  















								$desconto_total,















								$total_iva, 















                                total_amortizacoes,















                                total_pendente,















								$cod_fact















						);















						















                end if;















                















         end while;















         close facturas;















		 select * from facturas_temp;































END $$
/*!50003 SET SESSION SQL_MODE=@TEMP_SQL_MODE */  $$

