--
-- Definition of procedure `delete_produto`
--

DROP PROCEDURE IF EXISTS `delete_produto`;

DELIMITER $$

/*!50003 SET @TEMP_SQL_MODE=@@SQL_MODE, SQL_MODE='STRICT_TRANS_TABLES,STRICT_ALL_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,TRADITIONAL,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `delete_produto`(inicio int )
BEGIN































  declare cont int ;















  set cont = inicio;















  while cont <= 150 do















    delete from tb_preco where fk_produto = cont;















    delete from tb_stock where cod_produto_codigo = cont;















    delete from produto_imposto where fk_produto = cont;















    delete from produto_isento where fk_produto = cont;















    delete from tb_produto where codigo = cont;















    set cont = cont + 1;















  end while;















































END $$
