     $designacao VARCHAR(45) ,















     $preco FLOAT ,































     $cod_Tipo_Produto INT,















     $cod_fornecedores INT,















     $data_fabrico DATE,















     $data_expiracao DATE,















     $data_entrada DATE,















     $codBarra BIGINT,















     $status VARCHAR(10),















     $stocavel VARCHAR(10),































     $Codigo INT,















     $operacao INT































































)
BEGIN















  IF( $operacao = 1)  THEN














































                data_fabrico, data_expiracao, data_entrada, codBarra, status,  stocavel)































                VALUES($designacao, $preco, $cod_Tipo_Produto, $cod_fornecedores,















                $data_fabrico, $data_expiracao, $data_entrada , $codBarra, $status, $stocavel);































         ELSEIF ($operacao = 2)  THEN































                 UPDATE tb_produto















                 SET  designacao = $designacao,















                      preco = $preco,















                      cod_Tipo_Produto = $cod_Tipo_Produto,















                      cod_fornecedores = $cod_fornecedores,































                      data_expiracao = $data_expiracao,















                      data_entrada = $data_entrada,















