                VALUES($dataEntrada, $quantidade_existente, $quantidade_antiga,  $status, $cod_produto_codigo, $preco_venda, $quant_critica, $quant_baixa, $cod_armazem, $preco_venda_fabrica);































































































































         ELSEIF ($operacao = 2)  THEN































































































































                 UPDATE tb_stock































































                 SET  dataEntrada = $dataEntrada,































































                      quantidade_existente = $quantidade_existente,































































