DELIMITER ;

--
-- Definition of procedure `preencher_precos_padrao`
--

DROP PROCEDURE IF EXISTS `preencher_precos_padrao`;

DELIMITER $$

/*!50003 SET @TEMP_SQL_MODE=@@SQL_MODE, SQL_MODE='STRICT_TRANS_TABLES,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `preencher_precos_padrao`()
BEGIN
    DECLARE size_produto, cont INT DEFAULT 0;
    DECLARE v_codigo INT;

    -- Cursor para percorrer todos os produtos
    DECLARE cursor_produtos CURSOR FOR (
        SELECT codigo FROM tb_produto
    );

    -- Contar quantos produtos existem
    SELECT COUNT(*) FROM tb_produto INTO size_produto;

    OPEN cursor_produtos;
    SET cont = 1;

    WHILE cont <= size_produto DO
        FETCH cursor_produtos INTO v_codigo;

        -- Inserir preço RETALHO (0–5) se não existir
        IF NOT EXISTS (
            SELECT 1 FROM tb_preco
            WHERE fk_produto = v_codigo
              AND qtd_baixo = 0
              AND qtd_alto = 5
        ) THEN
                data,
                hora,
                preco_compra,
                percentagem_ganho,
                preco_venda,
                qtd_baixo,
                qtd_alto,
                preco_anterior,
                retalho,
                fk_produto,
                fk_usuario
            )
            VALUES (
                '2025-09-08',
                '08:00:00',
                100.000000,
                0.00,
                100.000000,
                0,
                5,
                100.000000,
                1,
                v_codigo,
                15
            );
        END IF;

        -- Inserir preço GROSSO (6–214748364) se não existir
        IF NOT EXISTS (
            SELECT 1 FROM tb_preco
            WHERE fk_produto = v_codigo
              AND qtd_baixo = 6
              AND qtd_alto = 214748364
        ) THEN
                data,
                hora,
                preco_compra,
                percentagem_ganho,
                preco_venda,
                qtd_baixo,
                qtd_alto,
                preco_anterior,
                retalho,
                fk_produto,
                fk_usuario
            )
            VALUES (
                '2025-09-08',
                '08:00:00',
                100.000000,
                0.00,
                100.000000,
                6,
                214748364,
                100.000000,
                1,
                v_codigo,
                15
            );
        END IF;

        SET cont = cont + 1;
    END WHILE;

    CLOSE cursor_produtos;
END $$
