-- Definition of procedure `proc_gerar_relatorio_mensal`
--

DROP PROCEDURE IF EXISTS `proc_gerar_relatorio_mensal`;

DELIMITER $$

/*!50003 SET @TEMP_SQL_MODE=@@SQL_MODE, SQL_MODE='STRICT_TRANS_TABLES,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `proc_gerar_relatorio_mensal`()
BEGIN

  TRUNCATE TABLE relatorio_mensal;

        data_relatorio,
        carne_bovina,
        carne_suina,
        carne_caprina,
        carne_ovina,
        aves,
        ovos,
        enchidos,
        sal,
        temperos,
        peixes
    )
    SELECT
        DATE(v.dataVenda),

        SUM(CASE WHEN tp.designacao = 'CARNE BOVINA'  THEN iv.total ELSE 0 END),
        SUM(CASE WHEN tp.designacao = 'CARNE SUINA'   THEN iv.total ELSE 0 END),
        SUM(CASE WHEN tp.designacao = 'CARNE CAPRINA' THEN iv.total ELSE 0 END),
        SUM(CASE WHEN tp.designacao = 'CARNE OVINA'   THEN iv.total ELSE 0 END),
        SUM(CASE WHEN tp.designacao = 'AVES'          THEN iv.total ELSE 0 END),
        SUM(CASE WHEN tp.designacao = 'OVOS'          THEN iv.total ELSE 0 END),
        SUM(CASE WHEN tp.designacao = 'ENCHIDOS'      THEN iv.total ELSE 0 END),
        SUM(CASE WHEN tp.designacao = 'SAL'           THEN iv.total ELSE 0 END),
        SUM(CASE WHEN tp.designacao = 'TEMPEROS'      THEN iv.total ELSE 0 END),
        SUM(CASE WHEN tp.designacao = 'PEIXES'        THEN iv.total ELSE 0 END)

    FROM tb_item_venda iv
    JOIN tb_venda v
        ON v.codigo = iv.codigo_venda
    JOIN tb_produto p
        ON p.codigo = iv.codigo_produto
    JOIN tb_tipo_produto tp
        ON tp.codigo = p.cod_Tipo_Produto
    where v.status_eliminado = 'false'
	and v.fk_documento = 1
    GROUP BY DATE(v.dataVenda);
END $$
/*!50003 SET SESSION SQL_MODE=@TEMP_SQL_MODE */  $$

DELIMITER ;

--
-- Definition of procedure `proc_importar_dados_notas_item_para_tb_item_venda`
--

DROP PROCEDURE IF EXISTS `proc_importar_dados_notas_item_para_tb_item_venda`;

DELIMITER $$

/*!50003 SET @TEMP_SQL_MODE=@@SQL_MODE, SQL_MODE='STRICT_TRANS_TABLES,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `proc_importar_dados_notas_item_para_tb_item_venda`(
	$cod_venda INT,
	$pk_nota VARCHAR(100)
)
BEGIN

	DECLARE $fk_mesas, $fk_lugares INT DEFAULT 1;
	DECLARE $quantidade, size_cursor,  cont  INT;
	DECLARE $valor_iva DOUBLE;
	DECLARE $motivo_isensao VARCHAR(150);
	DECLARE $desconto DOUBLE;
	DECLARE $total DECIMAL(10,2);
	DECLARE $codigo_isencao VARCHAR(50);
	DECLARE $fk_produto INT(11);
	DECLARE $fk_preco INT(10);


	DECLARE cursor_notas_itens CURSOR FOR  ( SELECT
		  quantidade,
		  valor_iva,
		  motivo_isensao,
		  desconto,
		  total,
		  codigo_isencao,
		  fk_produto,
		  fk_preco

		FROM notas_item i INNER JOIN notas n ON n.pk_nota = i.fk_nota WHERE n.cod_nota = $pk_nota
	);
	
	
	SELECT COUNT(*) FROM notas_item INTO size_cursor;
	
	SET cont = 1;
	OPEN cursor_notas_itens;
	
	WHILE cont <= size_cursor DO
		FETCH cursor_notas_itens INTO 
		
			$quantidade,
			$valor_iva,
			$motivo_isensao,
			$desconto,
			$total,
			$codigo_isencao,
			$fk_produto,
			$fk_preco;
		
		
			quantidade,
			valor_iva,
			motivo_isensao,
			desconto,
			total,
			codigo_isensao,
			codigo_produto,
			codigo_venda,
			fk_lugares,
			fk_mesas,
			fk_preco


		) VALUES(
			$quantidade,
			$valor_iva,
			$motivo_isensao,
			$desconto,
			$total,
			$codigo_isencao,
			$fk_produto,
			$cod_venda,
			$fk_lugares,
			$fk_mesas,
			$fk_preco
		
		);
		
		
		
		SET cont = cont + 1;
	END WHILE;
	
	


END $$
/*!50003 SET SESSION SQL_MODE=@TEMP_SQL_MODE */  $$

DELIMITER ;

--
-- Definition of procedure `proc_importar_dados_notas_para_tb_venda`
