DROP PROCEDURE IF EXISTS `proc_importar_dados_notas_para_tb_venda`;

DELIMITER $$

/*!50003 SET @TEMP_SQL_MODE=@@SQL_MODE, SQL_MODE='STRICT_TRANS_TABLES,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `proc_importar_dados_notas_para_tb_venda`()
BEGIN

  DECLARE size_notas, cont INT DEFAULT 0;
  
  DECLARE $pk_nota, $last_id INT;
  
  
