      FROM notas
	  
	  
	);

	  
	 SELECT COUNT(*) FROM notas INTO size_notas;
	 
	 OPEN cursor_notas;
	 SET cont = 1;
	 
	 WHILE cont <= size_notas DO
		FETCH cursor_notas INTO 
