			$hash_cod,
			$motivo,
			
			
			$ref_cod_fact,
			$total_por_extenso,
			$desconto_comercial,
			$desconto_finaceiro,
			
			
			$total_incidencia,
			$local_carga,
			$local_descarga,
			$codigo_usuario,
			
			
			$codigo_cliente,
			$idArmazemFK,
			$fk_documento,
			$fk_ano_economico,
			
			
			$fk_cambio,
			$cliente_nif,
			$total_incidencia_isento,
			$ref_data_fact;
			
			
			
			
		
			
			dataVenda,
			total_venda,
			performance,
			credito,
			
			
			valor_entregue,
			troco,
			hora,
			nome_cliente,
			
			
			status_eliminado,
			desconto_total,
			total_iva,
			total_geral,
			
			
			cod_fact,
			assinatura,
			hash_cod,
			obs,
			
			
			ref_cod_fact,
			total_por_extenso,
			desconto_comercial,
			desconto_financeiro,
			
			
			total_incidencia,
			local_carga,
			local_descarga,
			codigo_usuario,
			
			
			codigo_cliente,
			idArmazemFK,
			fk_documento,
			fk_ano_economico,
			
			
			fk_cambio,
			cliente_nif,
			total_incidencia_isento,
			ref_data_fact


		) VALUES(
		
			
			$dataNota, 
			$total_venda , 
			$performance,
			$credito,
			
			
			$valor_entregue,
			$troco,
			$hora,
			$nome_cliente,
			
			
			$status_eliminado,
			$desconto_total,
			$total_iva,
			$total_geral,
			
			
			$cod_nota,
			$assinatura,
			$hash_cod,
			$motivo,
			
			
