--
-- Definition of procedure `proc_importar_itens`
--

DROP PROCEDURE IF EXISTS `proc_importar_itens`;

DELIMITER $$

/*!50003 SET @TEMP_SQL_MODE=@@SQL_MODE, SQL_MODE='STRICT_TRANS_TABLES,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `proc_importar_itens`()
BEGIN

  DECLARE size_venda, cont INT DEFAULT 0;
  
  DECLARE $pk_nota, $last_id INT;
  
  DECLARE $codigo INT;
  DECLARE $cod_fact VARCHAR(100); 
  
  
  DECLARE cursor_venda CURSOR FOR   (
		SELECT codigo, cod_fact from tb_venda where fk_documento = 5
	);

	SELECT COUNT(*) FROM notas INTO size_venda;
	 
    OPEN cursor_venda;
    SET cont = 1;
	 
	WHILE cont <= size_venda DO
		FETCH cursor_venda INTO $codigo, $cod_fact;
		CALL proc_importar_dados_notas_item_para_tb_item_venda($codigo, $cod_fact);
		SET cont = cont + 1;
	END WHILE;
	





END $$
/*!50003 SET SESSION SQL_MODE=@TEMP_SQL_MODE */  $$

DELIMITER ;

