--
-- Definition of procedure `proc_itens_ticket`
--

DROP PROCEDURE IF EXISTS `proc_itens_ticket`;

DELIMITER $$

/*!50003 SET @TEMP_SQL_MODE=@@SQL_MODE, SQL_MODE='STRICT_TRANS_TABLES,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `proc_itens_ticket`(
	$cod_venda int 
)
begin
	
	
	declare $cod_produto int;
	declare $designacao varchar(400);
	declare $designacao_pai varchar(400);
	declare	$codFact varchar(100);
	declare $posicao int default 0;
	declare	$nome_cliente varchar(300);
	declare	$telefone_cliente varchar(300);
	declare	$usuario varchar(300);
	declare	$obs varchar(500);
	declare $data_entrega date;
	declare $cont, $tamaho int;

	
 	declare lista_itens cursor for  
 			( 
 				select 
					p.codigo , 
					p.designacao ,
					v.cod_fact,
					c.nome,
					c.telefone,
					u.nome ,
					v.dataVencimento  as data_entrega,
					i.obs as obs
				from tb_item_venda i 
				inner join tb_venda v on v.codigo  = i.codigo_venda 
				inner join tb_produto p on p.codigo  = i.codigo_produto 
				inner join tb_cliente c on c.codigo  = v.codigo_cliente 
				inner join tb_usuario u on u.codigo  = v.codigo_usuario 
				where v.codigo  = $cod_venda
 			) ; 
 		
 		
 	
	drop table if exists itens_ticket;
	create temporary table itens_ticket(
		designacao varchar(400),
		designacao_pai varchar(400),
		cod_fact varchar(100),
		posicao int,
		nome_cliente varchar(300),
		telefone_cliente varchar(300),
		usuario varchar(300),
		data_entrega date,
		obs varchar(500),
		cod_venda int
		
	);

	select 	count(*) from tb_item_venda i where i.codigo_venda = $cod_venda into $tamaho;
	open lista_itens;
	set $cont = 1;
	set $posicao = 1; 
	while $cont <= $tamaho do
		fetch lista_itens into $cod_produto, $designacao, $codFact, $nome_cliente, $telefone_cliente, $usuario, $data_entrega, $obs;
		
	
		if ( select exiteAssociado($cod_produto) ) then 
			
			select  getPosicaoItensTicketAssociados(
				$cod_produto,
				$designacao,
				$codFact, 
				$posicao, 
				$nome_cliente, 
				$telefone_cliente, 
				$usuario,
				$data_entrega, 
				$obs,  
				$cod_venda
			) into $posicao;
			
		else 
			 set $posicao = $posicao +1;
			
	   end if;
	   set $cont = $cont + 1;
	end while;
	close lista_itens;

	select * from itens_ticket;


 end $$
/*!50003 SET SESSION SQL_MODE=@TEMP_SQL_MODE */  $$

DELIMITER ;

--
-- Definition of procedure `proc_itens_ticket_associados`
--

DROP PROCEDURE IF EXISTS `proc_itens_ticket_associados`;

DELIMITER $$

/*!50003 SET @TEMP_SQL_MODE=@@SQL_MODE, SQL_MODE='STRICT_TRANS_TABLES,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `proc_itens_ticket_associados`(
	$cod_pai int , 
	$designacao_pai varchar(300),
	$codFact varchar(100), 
	$posicao int , 
	$nome_cliente varchar(200),
	$telefone_cliente varchar(100),
	$usuario varchar(100),
	$data_entrega date , 
	$obs varchar(500),
	$cod_venda int 
)
begin
	
	declare $designacao varchar(200);
	declare $tamanho, cont int;
	declare itens cursor for ( select designacao from tb_produto where cod_pai = $cod_pai );	
	select count(*) from tb_produto where cod_pai = $cod_pai into $tamanho;
	
	set cont = 1;
	open itens;
	while cont <= $tamanho do 
		fetch itens into $designacao;
			$designacao ,
			$designacao_pai,
			$codFact, 
			$posicao, 
			$nome_cliente,
			$telefone_cliente, 
			$usuario,
			$data_entrega, 
			$obs,
			$cod_venda
			);
		
		set $posicao = $posicao + 1;
		set cont = cont + 1;
	end while;
	close itens;

end $$
/*!50003 SET SESSION SQL_MODE=@TEMP_SQL_MODE */  $$

DELIMITER ;

--
-- Definition of procedure `relatorio_diario_by_usuario`
--

DROP PROCEDURE IF EXISTS `relatorio_diario_by_usuario`;

DELIMITER $$

/*!50003 SET @TEMP_SQL_MODE=@@SQL_MODE, SQL_MODE='STRICT_TRANS_TABLES,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `relatorio_diario_by_usuario`(

	$id_usuario int,
	$id_documento int,
	$data_1 datetime, 
	$data_2 datetime

)
begin
		
	select 
		v.cod_fact ,
		v.dataVenda as data_venda ,
		v.total_geral as valor,
		v.desconto_total as desconto,
		v.total_iva as iva,
		v.total_venda as total,
		d.nome  as nome_instituicao,
		d.nif  as nif_instituicao,
		d.enderecos  as enderecos_inituicao,
		getDataAberturaCaixaByUsuario($id_usuario, $data_1) as data_abertura,
		getDataFechoCaixaByUsuario($id_usuario) as data_fecho,
		(select getValorFormaPagamntoById(v.cod_fact, 1) ) as dinheiro,
		(select getValorFormaPagamntoById(v.cod_fact, 2)) as cartao,
		(select getValorFormaPagamntoById(v.cod_fact, 4)) as transferencia
	from tb_venda v
	inner join tb_usuario u on u.codigo  = v.codigo_usuario 
	inner join tb_dados_instituicao d
	where v.dataVenda between $data_1 and $data_2
	and  u.codigo  = $id_usuario
	and  v.fk_documento = $id_documento
	and  v.performance = 'false'
	and  v.credito = 'false'
	and  v.status_eliminado = 'false';

end $$
/*!50003 SET SESSION SQL_MODE=@TEMP_SQL_MODE */  $$

DELIMITER ;

