--
-- Definition of procedure `relatorio_diario_resumo_caixa`
--

DROP PROCEDURE IF EXISTS `relatorio_diario_resumo_caixa`;

DELIMITER $$

/*!50003 SET @TEMP_SQL_MODE=@@SQL_MODE, SQL_MODE='STRICT_TRANS_TABLES,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `relatorio_diario_resumo_caixa`(
	ano int,
    mes int
)
BEGIN


		select 

			c.usuario_abertura,
            c.usuario_fecho,
			i.fk_caixa,
			c.data_abertura as data_abertura,
			c.data_fecho as data_fecho,
			getValorDeclarado( date(c.data_abertura), 1)  as dinheiro_declarado,
			getValorDeclarado( date(c.data_abertura), 2)  as multicaixa_declarado,

			( 
				getValorDeclarado( date(c.data_abertura), 1)  
								+ 
				getValorDeclarado( date(c.data_abertura), 2)  


			)  as total_declarado ,

			getValorReal( date(c.data_abertura), 1)  as dinheiro_real,
			getValorReal( date(c.data_abertura), 2)  as multicaixa_real,
			(	
				getValorReal( date(c.data_abertura), 1)  
							+
				getValorReal( date(c.data_abertura), 2)  
			) as total_real,

            ( 

				getValorDeclarado( date(c.data_abertura), 1)  
						    	-
                getValorReal( date(c.data_abertura), 1)  

			) as diferenca_dinheiro , 
            ( 
				getValorDeclarado( date(c.data_abertura), 2)  
						    	- 
                getValorReal( date(c.data_abertura), 2)  
			) as diferenca_multicaixa 
			
		from 
			item_caixa i,
			caixa c,
			forma_pagamento f
		where
			c.pk_caixa = i.fk_caixa 							and 
			f.pk_forma_pagamento = i.fk_forma_pagamento  		and
            year(c.data_abertura) = ano 						and 
			month(c.data_abertura) = mes
		group by 
			date (c.data_abertura)

		order by
			date(c.data_abertura) asc;

END $$
/*!50003 SET SESSION SQL_MODE=@TEMP_SQL_MODE */  $$

DELIMITER ;

--
-- Definition of procedure `relatorio_diario_resumo_caixa_2`
--

DROP PROCEDURE IF EXISTS `relatorio_diario_resumo_caixa_2`;

DELIMITER $$

/*!50003 SET @TEMP_SQL_MODE=@@SQL_MODE, SQL_MODE='STRICT_TRANS_TABLES,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `relatorio_diario_resumo_caixa_2`(
	ano int,
    mes int)
begin
		select 
			c.pk_caixa,
			c.usuario_abertura,
		    c.usuario_fecho,
		    c.data_abertura ,
		    c.data_fecho ,
		    c.numero_vendas ,
		    getValorRealByIdCaixa( date(c.data_abertura), 1, c.pk_caixa)  as dinheiro,
			getValorRealByIdCaixa( date(c.data_abertura), 2, c.pk_caixa)  as cartao,
			getValorRealByIdCaixa( date(c.data_abertura), 4, c.pk_caixa)  as transferencia
		from caixa c
		where 
		year(c.data_abertura) = ano and 
		month(c.data_abertura) = mes;
END $$
/*!50003 SET SESSION SQL_MODE=@TEMP_SQL_MODE */  $$

DELIMITER ;

--
-- Definition of procedure `relatorio_diario_venda`
--

DROP PROCEDURE IF EXISTS `relatorio_diario_venda`;

DELIMITER $$

/*!50003 SET @TEMP_SQL_MODE=@@SQL_MODE, SQL_MODE='STRICT_TRANS_TABLES,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `relatorio_diario_venda`(ano int, id_mes int)
BEGIN
select  
    count(*) as numer_linha,
	date(data_abertura) as data , 
	SUM(numero_vendas) as numero_taloes,
	SUM(total_vendas) as total,
	SUM(total_desconto) as total_desconto,
	SUM(total_iva) as total_iva,
	SUM(total_iliquido) as total_iliquido
	from caixa 
	where  year(data_abertura) = ano 
	and month(data_abertura)  = id_mes
	group by DATE(data_abertura);
end $$
/*!50003 SET SESSION SQL_MODE=@TEMP_SQL_MODE */  $$

DELIMITER ;

--
-- Definition of procedure `relatorio_forma_pagamento`
--

DROP PROCEDURE IF EXISTS `relatorio_forma_pagamento`;

DELIMITER $$

/*!50003 SET @TEMP_SQL_MODE=@@SQL_MODE, SQL_MODE='STRICT_TRANS_TABLES,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `relatorio_forma_pagamento`(

    $data_1 date,
    $data_2 date,
    $id_armazem int,
    $id_documento int,
    $id_usuario int
)
BEGIN
  	SELECT
	f.designacao AS forma_pagamento,
	sum(i.valor) AS valor
	FROM forma_pagamento_item i
	INNER JOIN tb_venda v ON v.codigo = i.fk_venda
	INNER JOIN forma_pagamento f ON f.pk_forma_pagamento = i.fk_forma_pagamento
	WHERE 
		v.idArmazemFK = $id_armazem
		AND IF ( $id_usuario = 0,  v.codigo_usuario > 0,  v.codigo_usuario = $id_usuario )
		AND DATE(v.dataVenda) BETWEEN $data_1 AND $data_2
        AND v.fk_documento = $id_documento
		AND v.status_eliminado = 'false'
		AND v.credito = 'false'

	GROUP BY f.pk_forma_pagamento;
END $$
/*!50003 SET SESSION SQL_MODE=@TEMP_SQL_MODE */  $$

DELIMITER ;

--
-- Definition of procedure `relatorio_gorjeta`
--

DROP PROCEDURE IF EXISTS `relatorio_gorjeta`;

DELIMITER $$

/*!50003 SET @TEMP_SQL_MODE=@@SQL_MODE, SQL_MODE='STRICT_TRANS_TABLES,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `relatorio_gorjeta`(







	$data_1 date,







    $data_2 date















)
BEGIN















	DECLARE $cod_cartao INT DEFAULT 2;







    







	SELECT 







	







		v.cod_fact,  







        v.dataVenda,    







        u.nome,   







        v.total_geral AS total_factura,   







        forma.designacao AS forma_pagamento,  







        f.valor, 







        f.referencia AS ref,







        v.gorjeta







        







	FROM 







    







		tb_venda v







		INNER JOIN forma_pagamento_item f ON f.fk_venda = v.codigo







		INNER JOIN forma_pagamento forma ON forma.pk_forma_pagamento = f.fk_forma_pagamento







		INNER JOIN tb_usuario u ON u.codigo = v.codigo_usuario







        







	WHERE 







		forma.pk_forma_pagamento = $cod_cartao







	AND 	v.gorjeta > 0 







	AND 	DATE(v.dataVenda) BETWEEN $data_1 AND $data_2







    AND   	v.status_eliminado = 'false'







	AND 	v.credito = 'false';















END $$
/*!50003 SET SESSION SQL_MODE=@TEMP_SQL_MODE */  $$

DELIMITER ;

--
-- Definition of procedure `relatorio_mensal`
--

DROP PROCEDURE IF EXISTS `relatorio_mensal`;

DELIMITER $$

/*!50003 SET @TEMP_SQL_MODE=@@SQL_MODE, SQL_MODE='STRICT_TRANS_TABLES,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `relatorio_mensal`(
	$cod_doc int ,
	$cod_ano int ,
	$cod_mes int
)
begin
	select 
		d.designacao as documento,
		date(v.dataVenda) as data_venda,
		sum(v.total_venda)  , 
		sum(v.total_geral)
	from tb_venda v
	inner join documento d on d.pk_documento = v.fk_documento
	where year(v.dataVenda) = $cod_ano and month(v.dataVenda) = $cod_mes
	and v.status_eliminado  = 'false'
	and v.fk_documento = $cod_doc
	group by date(v.dataVenda)
	order by v.dataVenda asc;
end $$
/*!50003 SET SESSION SQL_MODE=@TEMP_SQL_MODE */  $$

DELIMITER ;

--
-- Definition of procedure `relatorio_produto_top`
--

DROP PROCEDURE IF EXISTS `relatorio_produto_top`;

DELIMITER $$

/*!50003 SET @TEMP_SQL_MODE=@@SQL_MODE, SQL_MODE='STRICT_TRANS_TABLES,STRICT_ALL_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,TRADITIONAL,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `relatorio_produto_top`(top int, ano int, mes int )
BEGIN















	select 















		p.codigo,















		p.designacao , 















        t.designacao as subfamilia,















        sum(i.quantidade) as qtd,  















        sum(i.total) as subtotal















	from 















		tb_item_venda i, 















        tb_produto p, 















        tb_venda v,















        tb_tipo_produto t















	where 















		i.codigo_produto = p.codigo















		and v.codigo = codigo_venda















        and t.codigo = p.cod_Tipo_Produto















		and year(v.dataVenda) = ano 















		and month(v.dataVenda) = mes















	group by 















		p.codigo















    order 















		by qtd desc















    limit 















		20;















END $$
/*!50003 SET SESSION SQL_MODE=@TEMP_SQL_MODE */  $$

DELIMITER ;

--
-- Definition of procedure `rh_folha_salario`
--

DROP PROCEDURE IF EXISTS `rh_folha_salario`;

DELIMITER $$

/*!50003 SET @TEMP_SQL_MODE=@@SQL_MODE, SQL_MODE='NO_ENGINE_SUBSTITUTION' */ $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `rh_folha_salario`(































	$periodo VARCHAR(75) 















            















)
BEGIN































		SELECT 































		r.pk_recibo_rh AS id_recibo, 















		f.numero_funcionario AS numero_funcrionario,















		f.idFuncionario AS id_funcionario,















		f.nome AS nome_funcionario, 















		















		(















			SELECT iban FROM tb_conta WHERE idFuncionarioFK = id_funcionario















			















		) AS iban,















        















        (















			SELECT numero_conta FROM tb_conta WHERE idFuncionarioFK = id_funcionario















			















		) AS numero_banco,















		















		( 















			SELECT SUM(remuneracao) AS total_subsidio FROM item_recibo_rh WHERE  fk_recibo_rh = id_recibo















			















		) AS total_remunueracao,















		















		( 















			SELECT SUM(desconto) AS total_subsidio FROM item_recibo_rh WHERE  fk_recibo_rh = id_recibo















			















		) AS total_desconto















		















		















	FROM  































		recibo_rh r, 















		tb_funcionario f















		















	WHERE 































		r.fk_funcionario = f.idFuncionario















        















	AND















    















		r.periodo = $periodo































	GROUP BY 















    















		r.fk_funcionario















		















	ORDER BY 















    















		f.nome ASC;















































END $$
/*!50003 SET SESSION SQL_MODE=@TEMP_SQL_MODE */  $$

DELIMITER ;

--
-- Definition of procedure `rh_folha_salario_completa`
--

DROP PROCEDURE IF EXISTS `rh_folha_salario_completa`;

DELIMITER $$

/*!50003 SET @TEMP_SQL_MODE=@@SQL_MODE, SQL_MODE='NO_ENGINE_SUBSTITUTION' */ $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `rh_folha_salario_completa`(
	$periodo VARCHAR(75) 
)
BEGIN
		SELECT 
		r.pk_recibo_rh AS id_recibo, 
		f.numero_funcionario AS numero_funcrionario,
		f.idFuncionario AS id_funcionario,
		f.nome AS nome_funcionario, 
		(
			SELECT iban FROM tb_conta WHERE idFuncionarioFK = id_funcionario
		) AS conta_bancaria,
	    (
			SELECT total_pago FROM recibo_rh WHERE pk_recibo_rh = id_recibo
		) AS total_pago,
		(
			SELECT total_desconto FROM recibo_rh WHERE pk_recibo_rh = id_recibo
		) AS total_desconto,
		( 
			SELECT vencimento AS total_subsidio FROM item_recibo_rh WHERE descricao LIKE 'Venc%' AND  fk_recibo_rh = id_recibo
		) AS vencimento,
		( 
			SELECT SUM(remuneracao) AS total_subsidio FROM item_recibo_rh WHERE descricao LIKE 'Sub%' AND  fk_recibo_rh = id_recibo
		) AS total_subsidio,

		( 
			SELECT SUM(desconto) AS total_subsidio FROM item_recibo_rh WHERE descricao LIKE 'Falt%' AND  fk_recibo_rh = id_recibo

		) AS total_falta,
		( 
			SELECT SUM(desconto) AS total_subsidio FROM item_recibo_rh WHERE descricao LIKE 'ins%' AND  fk_recibo_rh = id_recibo
		) AS total_seguranca_social,
		( 
			SELECT SUM(desconto) AS total_subsidio FROM item_recibo_rh WHERE descricao LIKE 'irt%' AND  fk_recibo_rh = id_recibo
		) AS total_irt
	FROM 
		recibo_rh r, 
		tb_funcionario f
	WHERE 
		r.fk_funcionario = f.idFuncionario
	AND
		r.periodo = $periodo
	GROUP BY 
		r.fk_funcionario
	ORDER BY 
		f.nome ASC;
END $$
/*!50003 SET SESSION SQL_MODE=@TEMP_SQL_MODE */  $$

DELIMITER ;

